function learningOverview(){const items=state.items||[],history=state.paragraphPracticeHistory||[],last14=Date.now()-14*DAY,reviewed=items.filter(x=>(x.attempts||[]).some(a=>Date.parse(a.date||a.at)>=last14)).length,mastered=items.filter(x=>String(x.status).startsWith('Mastered')).length,memorized=items.filter(x=>x.status==='Memorized').length,catchup=catchupBuckets(state);return `<div class="eyebrow">Long-term learning</div><h1>Learning Overview</h1><p class="muted">Your saved learning progress and practice history.</p><div class="grid"><section class="panel stat"><span class="muted small">Expressions saved</span><strong>${items.length}</strong></section><section class="panel stat"><span class="muted small">Paragraph attempts</span><strong>${history.length}</strong></section><section class="panel stat"><span class="muted small">Reviewed in 14 days</span><strong>${reviewed}</strong></section></div><section class="panel"><h2>Learning stages</h2><p class="small muted">${(state.learningMemory?.events||[]).length} attempts tracked in learning memory · ${(state.learningMemory?.events||[]).flatMap(e=>e.observed||[]).filter(o=>o.independent).length} independent expression uses observed (not verified mastery).</p><div class="cardline row"><span>Memorized</span><strong>${memorized}</strong></div><div class="cardline row"><span>Mastered</span><strong>${mastered}</strong></div><div class="cardline row"><span>Historical items awaiting an initial review</span><strong>${catchup.counts.baseline}</strong></div><div class="cardline row"><span>Overdue reviews</span><strong>${catchup.counts.overdue}</strong></div><p class="small muted">Unknown dates are not treated as overdue. Progress reflects records saved in this browser.</p><div class="actions"><button id="overview-practice" class="primary">Start conversation review</button><button id="overview-library">Browse library</button></div></section></div>`}
function materialFingerprint(){const d=state.captureDraft||{};return JSON.stringify([d.text||'',d.context||'',d.source||'Work'])}
function capture(){const d=state.captureDraft||{},review=d.review,valid=review&&review.fingerprint===materialFingerprint();return `<div class="eyebrow">Your own learning material</div><h1>Review before you save.</h1><p class="muted">Paste your writing, notes, or several sentences. AI checks the wording and suggests useful expressions. You choose what enters your library.</p><section class="panel"><label for="capture-source">Source</label><select id="capture-source" ${ui.busy?'disabled':''}>${['Work','TV / Movies','Conversations','Other'].map(x=>`<option value="${x}" ${(d.source||'Work')===x?'selected':''}>${x}</option>`).join('')}</select><div class="inputrow"><label for="capture-text">Your writing or learning material</label><textarea id="capture-text" maxlength="12000" placeholder="Paste sentences, a paragraph, or mixed notes…" ${ui.busy?'disabled':''}>${escapeHtml(d.text||'')}</textarea><label for="capture-context">Context (optional)</label><textarea id="capture-context" placeholder="What were you trying to say? Where would you use it?" ${ui.busy?'disabled':''}>${escapeHtml(d.context||'')}</textarea></div><button id="capture-analyze" class="primary" ${ui.busy?'disabled':''}>${ui.busy?'Reviewing your writing…':valid?'Review again':'Review with AI'}</button><p class="small muted">Nothing is added to your library until you review and save your selection.</p>${d.error?`<p class="danger" role="alert">${escapeHtml(d.error)} Your writing is saved locally; try again later.</p>`:''}</section>${valid?`<section class="panel" id="capture-review"><h2>AI review</h2><p>${escapeHtml(review.summary)}</p><details><summary>See the revised writing</summary><p class="polished-text">${escapeHtml(review.correctedText)}</p></details><h3 style="margin-top:24px">Choose what to learn</h3><p class="small muted">Review each correction. You can edit a suggestion before saving.</p>${review.candidates.map((x,i)=>`<div class="cardline"><label class="material-choice"><input type="checkbox" data-capture-select="${i}" ${x.selected?'checked':''}> Save this expression</label><label for="candidate-${i}" class="small muted">Reviewed expression</label><textarea id="candidate-${i}" data-capture-edit="${i}" maxlength="1000">${escapeHtml(x.text)}</textarea>${x.original?`<p class="small muted">From your writing: ${escapeHtml(x.original)}</p>`:''}<p class="small">${escapeHtml(x.explanation)}</p><p class="small muted">${escapeHtml(x.context)}</p></div>`).join('')}<button id="capture-save" class="primary" ${review.candidates.some(x=>x.selected&&x.text.trim())?'':'disabled'}>Save selected expressions</button>${d.savedMessage?`<p class="small" role="status">${escapeHtml(d.savedMessage)}</p>`:''}</section>`:''}`}
async function analyzeCapture(){if(ui.busy)return;state.captureDraft??={};const d=state.captureDraft,text=(d.text||'').trim();if(!text)return alert('Paste some writing first.');if(text.length>12000)return alert('Please keep each review under 12,000 characters.');const fingerprint=materialFingerprint();d.error=null;d.savedMessage=null;ui.busy=true;save();render();try{const r=await fetch('/api/analyze-material',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({answer:text,context:d.context||'',source:d.source||'Work'})});const result=await r.json();if(!r.ok)throw Error(result.error||'AI review unavailable');if(typeof result.correctedText!=='string'||!Array.isArray(result.candidates))throw Error('The AI review was incomplete. Please try again.');const seen=new Set();const candidates=result.candidates.filter(x=>{if(!x||typeof x.text!=='string'||!x.text.trim()||x.text.length>1000)return false;const k=normalize(x.original||x.text);if(seen.has(k))return false;seen.add(k);return true}).slice(0,12).map(x=>({...x,text:x.text.trim(),selected:true}));if(!candidates.length)throw Error('No suitable learning expressions were found. Try a more specific passage.');if(fingerprint===materialFingerprint())d.review={fingerprint,summary:String(result.summary||''),correctedText:result.correctedText,candidates};}catch(e){d.error=e.message}finally{ui.busy=false;save();render()}}
function saveCapture(){const d=state.captureDraft,review=d?.review;if(!review||review.fingerprint!==materialFingerprint())return alert('Review the current writing with AI before saving.');const selected=review.candidates.filter(x=>x.selected&&x.text.trim());if(!selected.length)return;let added=0,merged=0;for(const candidate of selected){const text=candidate.text.trim(),norm=normalize(text).replace(/[’‘]/g,"'");const existing=[...state.items,...(state.paragraphs||[])].find(x=>normalize(x.target||x.text||'').replace(/[’‘]/g,"'")===norm);if(existing){merged++;existing.captureContexts??=[];if(candidate.context&&!existing.captureContexts.includes(candidate.context))existing.captureContexts.push(candidate.context);continue}state.items.push({id:'capture:'+Date.now()+':'+Math.random().toString(36).slice(2,8),title:text.slice(0,75),text,target:text,expression:text,context:candidate.context||d.context||'Use this expression in conversation.',hint:'',source:'AI-reviewed writing · '+(d.source||'Work'),originalText:candidate.original||'',reviewExplanation:candidate.explanation||'',status:'Saved',streak:0,reviewStep:0,due:null,nextReviewAt:null,createdAt:new Date().toISOString(),attempts:[],kind:'expression'});added++}
 state.materialReviewHistory??=[];state.materialReviewHistory.push({id:'material:'+Date.now(),at:new Date().toISOString(),originalText:d.text,correctedText:review.correctedText,source:d.source||'Work',selected:selected.map(x=>({text:x.text,original:x.original,explanation:x.explanation}))});d.savedMessage=`${added} expression(s) added${merged?`, ${merged} already in your library`:''}. Your original writing is retained.`;for(const x of selected)x.selected=false;save();render()}
