 const entry={id,at,sessionId:d.id,turn:d.turn,sourceId:source.id,partner:t.partner,intent:t.intent,answer,mode};state.dialoguePracticeHistory??=[];state.dialoguePracticeHistory.push(entry);state.dialoguePracticeHistory=state.dialoguePracticeHistory.slice(-1000);
