 recordParagraphMemory(state,{id,scenarioId:d.id+':turn:'+d.turn,answer,chunks:source.chunks,mode,kind:'dialogue'});
 rememberDialogueProgress();t.answer=answer;t.feedback=null;ui.result={answer};ui.ai=null;save();
 const transcript=d.turns.slice(0,d.turn).map(x=>({partner:x.partner,answer:x.answer}));
 await askAI(answer,JSON.stringify({task:'Dialogue roleplay. Evaluate this English response to the partner. Continue this exact conversation, not a disconnected exercise.',scene:d.scene.place,partnerRole:d.scene.who,partnerSaidZh:t.partner,learnerIntendedZh:t.intent,mode:'Chinese dialogue line to natural English',earlierTurns:transcript,learningMaterial:source.item?.target||source.item?.text||source.chunks}), 'No fixed English target. Accept natural alternatives that preserve the intended meaning. If Chinese intent is provided, check completeness as well as grammar and conversational tone.',id);
 t.feedback=ui.ai;entry.feedback=ui.ai;
 if(source.item&&ui.ai?.practicePassed===true){const item=source.item;if(item.due&&item.due<=Date.now()||item.nextReviewAt&&Date.parse(item.nextReviewAt)<=Date.now()){const status=item.status,streak=item.streak;Object.assign(item,coreAdvanceReview(item,true));item.status=status;item.streak=streak;item.reviewHistory.at(-1).source='AI-assessed dialogue; mastery unchanged';}}
