function exportData(){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=url;a.download='daily-english-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
let pendingImport=null;
function showImportPreview(incoming){try{const stats=previewMerge(state,incoming);pendingImport=incoming;setView('settings');const el=$('import-preview');if(!el)return;el.innerHTML=`<div class="feedback"><h3>Import preview</h3><p><strong>${stats.added}</strong> new expressions · <strong>${stats.matched}</strong> matched expressions · <strong>${stats.attempts}</strong> new recorded attempts · <strong>${stats.paragraphs}</strong> source paragraphs · <strong>${stats.errorPatterns}</strong> historical patterns.</p><p class="small muted">${stats.reconstructed?'Reconstructed seed: incomplete practice history, unknown review dates preserved.':'User-provided backup.'} Existing data remains authoritative. Export a backup before proceeding.</p><div class="actions"><button id="confirm-import" class="primary">Merge without overwriting</button><button id="cancel-import">Cancel</button></div></div>`;document.getElementById('confirm-import').onclick=()=>{try{const snapshot=JSON.stringify(state);localStorage.setItem('daily-english-ai-v2-rollback-'+Date.now(),snapshot);const merged=mergeHistory(state,pendingImport);state=merged;pendingImport=null;save();alert('Merge completed. Existing progress and drafts preserved.');render()}catch(e){alert('Merge failed: '+e.message)}};document.getElementById('cancel-import').onclick=()=>{pendingImport=null;render()}}catch(e){alert('Import rejected: '+e.message)}}
async function importData(e){const file=e.target.files?.[0];if(!file)return;if(file.size>3_000_000){alert('File too large.');return}try{showImportPreview(JSON.parse(await file.text()))}catch(err){alert('Import failed: '+err.message)}}
