// One-time non-destructive seed merge. Browser data remains the source of truth.
if(!state.bundledHistoryImported){fetch('/daily-english-history.json').then(r=>{if(!r.ok)throw Error('Bundled history unavailable');return r.json()}).then(seed=>{if(state.bundledHistoryImported)return;const previous=JSON.stringify(state);const merged=mergeHistory(state,seed);localStorage.setItem('daily-english-ai-v2-rollback-initial',previous);merged.bundledHistoryImported=true;state=merged;save();render()}).catch(err=>{console.warn('History seed not merged:',err.message)})}
